 if(p==='takes'&&S.have.takes&&s){name=s.id+' · Video-Takes';sub=S.chosen[at()]?'Take '+S.chosen[at()]+' ausgewählt':'Auswahl offen';body=group('Produktion',prop('Route',s.source)+prop('Dauer',s.duration+' s')+prop('Eingaben','Freigegebene Shot-Anker')+B('video-cost','Fehlende Takes erzeugen',{disabled:!isEdit()||S.shots.every((_,i)=>S.takes[i]?.length),primary:true})+B('retake-cost','Zusätzlichen Take erzeugen',{disabled:!isEdit()||s.source==='Importierter Clip'||!S.takes[at()]?.length,cls:'control'}))+group('Herkunft',prop('Provider','Demo-Route')+prop('Modell','Keine Live-Verbindung')+prop('Beispielkosten',s.source==='Importierter Clip'?'0,00 €':'0,40 € / Take')+'<small>Nur ausführbare Provider werden im Produkt angeboten.</small>')+(S.previousTakes?group('Frühere Revision',prop('Revision',S.previousTakes.revision)+B('mode:history','Frühere Takes ansehen',{cls:'control'})):'');}

