function gate(){let action='';if(S.running)action=B('stop-job','Auftrag stoppen',{cls:'control'});else if(S.covered[S.view])action=B('open:'+S.current,'Aktuellen Schritt öffnen',{cls:'control'});else if(S.done[S.view])action=B('revise','Revision beginnen',{cls:'control'});else if(S.view!==S.current)action=B('open:'+S.current,'Aktuellen Schritt öffnen',{cls:'control'});else action=B(S.view==='finish'?'export':'approve',S.view==='finish'?'Ausgabe simulieren':'✓ Freigeben',{primary:true,disabled:!readiness()});
 $('#nd-gate').hidden=S.view==='edit'&&S.have.edit;
 $('#nd-gate').innerHTML=$('#nd-gate').hidden?'':`<div class="phase-state"><b>${S.running?'Produktion läuft':labels[S.current]+' · '+(S.done[S.current]?'abgeschlossen':'aktueller Schritt')}</b><small>${E(S.notice||reason())}</small></div>${action}`;
 $('#nd-status').innerHTML=`<span>CLICKDUMMY</span><label>Beispiel <select data-demo ${S.running?'disabled':''}>${['Storyboard','Leer','Audio','Shotplanung','References','Review','Takes','Schnitt','Finish'].map(x=>`<option ${x===S.fixture?'selected':''}>${x}</option>`).join('')}</select></label><span class="grow"></span>${B('budget',`Budget ${money(S.cost)} / ${money(S.cap)}`,{disabled:S.running})}<span class="optional">${S.view==='edit'?'Schnitt-Demo':'Keine echten Aufträge'}</span>${S.view==='edit'&&S.have.edit?action.replace('✓ Freigeben','Schnitt abschließen'):''}`;
}
